import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import EnhancedBillUpload from './EnhancedBillUpload';
import TripBudgetDashboard from './TripBudgetDashboard';
import CompletedTripsEmployee from './CompletedTripsEmployee';

const ProfessionalEmployeeDashboard = () => {
    const navigate = useNavigate();
    const [profile, setProfile] = useState(null);
    const [activeTab, setActiveTab] = useState('overview');
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState('');
    const [myBills, setMyBills] = useState([]);
    const [dashboardStats, setDashboardStats] = useState({
        totalBills: 0,
        pendingBills: 0,
        approvedBills: 0,
        rejectedBills: 0,
        totalAmount: 0,
        activeTrips: 0,
        completedTrips: 0
    });

    useEffect(() => {
        const token = localStorage.getItem('token');
        if (!token) {
            navigate('/login');
            return;
        }
        
        fetchProfile();
        fetchDashboardData();
    }, [navigate]);

    const fetchProfile = async () => {
        try {
            const token = localStorage.getItem('token');
            const response = await fetch('http://localhost:8000/profile', {
                headers: {
                    'Authorization': `Bearer ${token}`,
                    'Content-Type': 'application/json'
                }
            });

            if (response.ok) {
                const data = await response.json();
                setProfile(data);
                
                if (data.role === 'manager') {
                    navigate('/manager-dashboard');
                }
            } else {
                throw new Error('Failed to fetch profile');
            }
        } catch (err) {
            console.error('Error fetching profile:', err);
            if (err.response?.status === 401) {
                localStorage.removeItem('token');
                navigate('/login');
            }
        }
    };

    const fetchDashboardData = async () => {
        try {
            setLoading(true);
            const token = localStorage.getItem('token');
            
            // Fetch employee bills and trips data
            const [billsRes, completedTripsRes] = await Promise.all([
                fetch('http://localhost:8000/bills/my-bills', {
                    headers: { 'Authorization': `Bearer ${token}` }
                }).catch(() => ({ ok: false })),
                fetch('http://localhost:8000/trip-budget/completed-trips', {
                    headers: { 'Authorization': `Bearer ${token}` }
                }).catch(() => ({ ok: false }))
            ]);

            // Process bills data
            let billsData = [];
            if (billsRes.ok) {
                const billsResponse = await billsRes.json();
                billsData = billsResponse.bills || billsResponse || [];
                setMyBills(billsData);
            }

            // Process completed trips data
            let completedTripsData = [];
            if (completedTripsRes.ok) {
                const tripsResponse = await completedTripsRes.json();
                completedTripsData = tripsResponse.completed_trips || [];
            }

            // Calculate dashboard statistics
            const stats = {
                totalBills: billsData.length,
                pendingBills: billsData.filter(bill => bill.status === 'pending').length,
                approvedBills: billsData.filter(bill => bill.status === 'approved').length,
                rejectedBills: billsData.filter(bill => bill.status === 'rejected').length,
                totalAmount: billsData.reduce((sum, bill) => sum + (parseFloat(bill.amount) || 0), 0),
                activeTrips: 0, // This would come from active trips API
                completedTrips: completedTripsData.length
            };

            setDashboardStats(stats);
            setError('');
        } catch (err) {
            console.error('Error fetching dashboard data:', err);
            setError('Failed to load dashboard data');
        } finally {
            setLoading(false);
        }
    };

    const formatCurrency = (amount) => {
        return new Intl.NumberFormat('en-US', {
            style: 'currency',
            currency: 'USD'
        }).format(amount || 0);
    };

    const formatDate = (dateString) => {
        if (!dateString) return 'N/A';
        return new Date(dateString).toLocaleDateString('en-US', {
            year: 'numeric',
            month: 'short',
            day: 'numeric'
        });
    };

    const getStatusBadge = (status) => {
        const statusConfig = {
            'pending': { class: 'status-pending', text: 'Pending' },
            'approved': { class: 'status-approved', text: 'Approved' },
            'rejected': { class: 'status-rejected', text: 'Rejected' },
            'under_review': { class: 'status-review', text: 'Under Review' }
        };
        
        const config = statusConfig[status] || { class: 'status-unknown', text: status };
        return <span className={`status-badge ${config.class}`}>{config.text}</span>;
    };

    const logout = () => {
        localStorage.removeItem('token');
        navigate('/login');
    };

    const goToProfile = () => {
        navigate('/profile');
    };

    if (loading) {
        return (
            <div className="professional-employee-dashboard">
                <div className="loading-container">
                    <div className="loading-spinner"></div>
                    <h3>Loading Your Dashboard...</h3>
                </div>
            </div>
        );
    }

    return (
        <div className="professional-employee-dashboard">
            {/* Header */}
            <div className="dashboard-header">
                <div className="header-content">
                    <div className="header-left">
                        <h1 className="dashboard-title">Employee Dashboard</h1>
                        {profile && (
                            <p className="welcome-text">
                                Welcome back, {profile.full_name || profile.username}
                            </p>
                        )}
                    </div>
                    <div className="header-actions">
                        <button className="btn btn-secondary" onClick={goToProfile}>
                            👤 Profile
                        </button>
                        <button className="btn btn-danger" onClick={logout}>
                            🚪 Logout
                        </button>
                    </div>
                </div>
            </div>

            {/* Statistics Overview */}
            <div className="stats-overview">
                <div className="stats-grid">
                    <div className="stat-card primary">
                        <div className="stat-icon">📄</div>
                        <div className="stat-content">
                            <div className="stat-number">{dashboardStats.totalBills}</div>
                            <div className="stat-label">Total Bills</div>
                        </div>
                    </div>
                    
                    <div className="stat-card warning">
                        <div className="stat-icon">⏳</div>
                        <div className="stat-content">
                            <div className="stat-number">{dashboardStats.pendingBills}</div>
                            <div className="stat-label">Pending Approval</div>
                        </div>
                    </div>
                    
                    <div className="stat-card success">
                        <div className="stat-icon">✅</div>
                        <div className="stat-content">
                            <div className="stat-number">{dashboardStats.approvedBills}</div>
                            <div className="stat-label">Approved Bills</div>
                        </div>
                    </div>
                    
                    <div className="stat-card info">
                        <div className="stat-icon">💰</div>
                        <div className="stat-content">
                            <div className="stat-number">{formatCurrency(dashboardStats.totalAmount)}</div>
                            <div className="stat-label">Total Expenses</div>
                        </div>
                    </div>
                </div>
            </div>

            {/* Navigation Tabs */}
            <div className="dashboard-navigation">
                <div className="nav-tabs">
                    <button 
                        className={`nav-tab ${activeTab === 'overview' ? 'active' : ''}`}
                        onClick={() => setActiveTab('overview')}
                    >
                        📊 Overview
                    </button>
                    <button 
                        className={`nav-tab ${activeTab === 'upload' ? 'active' : ''}`}
                        onClick={() => setActiveTab('upload')}
                    >
                        📤 Upload Bill
                    </button>
                    <button 
                        className={`nav-tab ${activeTab === 'my-bills' ? 'active' : ''}`}
                        onClick={() => setActiveTab('my-bills')}
                    >
                        📋 My Bills ({dashboardStats.totalBills})
                    </button>
                    <button 
                        className={`nav-tab ${activeTab === 'trips' ? 'active' : ''}`}
                        onClick={() => setActiveTab('trips')}
                    >
                        ✈️ Trip Management
                    </button>
                    <button 
                        className={`nav-tab ${activeTab === 'completed' ? 'active' : ''}`}
                        onClick={() => setActiveTab('completed')}
                    >
                        📚 Completed Trips
                    </button>
                </div>
            </div>

            {/* Tab Content */}
            <div className="dashboard-content">
                {activeTab === 'overview' && (
                    <div className="overview-content">
                        <div className="overview-grid">
                            {/* Quick Actions */}
                            <div className="overview-card">
                                <h3>🚀 Quick Actions</h3>
                                <div className="quick-actions">
                                    <button 
                                        className="action-btn primary"
                                        onClick={() => setActiveTab('upload')}
                                    >
                                        📤 Upload New Bill
                                    </button>
                                    <button 
                                        className="action-btn secondary"
                                        onClick={() => setActiveTab('my-bills')}
                                    >
                                        📋 View My Bills ({dashboardStats.totalBills})
                                    </button>
                                    <button 
                                        className="action-btn tertiary"
                                        onClick={() => setActiveTab('trips')}
                                    >
                                        ✈️ Manage Trips
                                    </button>
                                </div>
                            </div>

                            {/* Bills Summary */}
                            <div className="overview-card">
                                <h3>📊 Bills Summary</h3>
                                <div className="bills-summary">
                                    <div className="summary-item">
                                        <span className="summary-label">Total Submitted:</span>
                                        <span className="summary-value">{dashboardStats.totalBills}</span>
                                    </div>
                                    <div className="summary-item">
                                        <span className="summary-label">Pending Review:</span>
                                        <span className="summary-value">{dashboardStats.pendingBills}</span>
                                    </div>
                                    <div className="summary-item">
                                        <span className="summary-label">Approved:</span>
                                        <span className="summary-value">{dashboardStats.approvedBills}</span>
                                    </div>
                                    <div className="summary-item">
                                        <span className="summary-label">Total Amount:</span>
                                        <span className="summary-value">{formatCurrency(dashboardStats.totalAmount)}</span>
                                    </div>
                                </div>
                            </div>

                            {/* Trip Summary */}
                            <div className="overview-card">
                                <h3>✈️ Trip Summary</h3>
                                <div className="trip-summary">
                                    <div className="summary-item">
                                        <span className="summary-label">Completed Trips:</span>
                                        <span className="summary-value">{dashboardStats.completedTrips}</span>
                                    </div>
                                    <div className="summary-item">
                                        <span className="summary-label">Active Trips:</span>
                                        <span className="summary-value">{dashboardStats.activeTrips}</span>
                                    </div>
                                </div>
                            </div>

                            {/* Recent Activity */}
                            <div className="overview-card">
                                <h3>🕒 Recent Activity</h3>
                                <div className="recent-activity">
                                    {myBills.slice(0, 3).map((bill, index) => (
                                        <div key={index} className="activity-item">
                                            <div className="activity-icon">📄</div>
                                            <div className="activity-details">
                                                <div className="activity-title">{bill.filename}</div>
                                                <div className="activity-meta">
                                                    {formatDate(bill.date)} • {formatCurrency(bill.amount)}
                                                </div>
                                            </div>
                                            <div className="activity-status">
                                                {getStatusBadge(bill.status)}
                                            </div>
                                        </div>
                                    ))}
                                    {myBills.length === 0 && (
                                        <p className="no-activity">No recent activity</p>
                                    )}
                                </div>
                            </div>
                        </div>
                    </div>
                )}

                {activeTab === 'upload' && (
                    <div className="upload-content">
                        <EnhancedBillUpload onUploadSuccess={fetchDashboardData} />
                    </div>
                )}

                {activeTab === 'my-bills' && (
                    <div className="bills-content">
                        <h3>📋 My Bills</h3>
                        {myBills.length === 0 ? (
                            <div className="empty-state">
                                <div className="empty-icon">📄</div>
                                <h4>No bills yet</h4>
                                <p>Start by uploading your first bill!</p>
                                <button 
                                    className="btn btn-primary"
                                    onClick={() => setActiveTab('upload')}
                                >
                                    📤 Upload Bill
                                </button>
                            </div>
                        ) : (
                            <div className="bills-list">
                                {myBills.map((bill, index) => (
                                    <div key={index} className={`bill-item ${bill.status}`}>
                                        <div className="bill-header">
                                            <h4>{bill.filename}</h4>
                                            {getStatusBadge(bill.status)}
                                        </div>
                                        <div className="bill-details">
                                            <div className="bill-info">
                                                <span><strong>Date:</strong> {formatDate(bill.date)}</span>
                                                <span><strong>Amount:</strong> {formatCurrency(bill.amount)}</span>
                                                <span><strong>Category:</strong> {bill.category || 'N/A'}</span>
                                                <span><strong>Vendor:</strong> {bill.vendor || 'N/A'}</span>
                                            </div>
                                            {bill.remarks && (
                                                <div className="bill-remarks">
                                                    <strong>Remarks:</strong> {bill.remarks}
                                                </div>
                                            )}
                                        </div>
                                    </div>
                                ))}
                            </div>
                        )}
                    </div>
                )}

                {activeTab === 'trips' && (
                    <div className="trips-content">
                        <TripBudgetDashboard />
                    </div>
                )}

                {activeTab === 'completed' && (
                    <div className="completed-content">
                        <CompletedTripsEmployee />
                    </div>
                )}
            </div>

            {/* Error Display */}
            {error && (
                <div className="error-message">
                    <span>❌ {error}</span>
                    <button 
                        className="btn btn-secondary"
                        onClick={fetchDashboardData}
                    >
                        Retry
                    </button>
                </div>
            )}
        </div>
    );
};

export default ProfessionalEmployeeDashboard;
